import{_ as o,o as t,c as r,a3 as a}from"./chunks/framework.C_NFtyrq.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),c={name:"explanation/concepts.md"};function d(s,e,n,i,l,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The vocabulary of bupha — each term defined once.</p><h2 id="the-pipeline-shape" tabindex="-1">The pipeline shape <a class="header-anchor" href="#the-pipeline-shape" aria-label="Permalink to &quot;The pipeline shape&quot;">​</a></h2><ul><li><strong>Source</strong> — the ingest edge: a long-running producer of normalized <code>(repo, ref, sha, sender)</code> pushes. Impls: <code>github-webhook</code> (HMAC-verified deliveries) and <code>sturn-wal</code> (WAL snapshot events).</li><li><strong><code>Trigger</code></strong> — the narrower per-request port a webhook <code>Source</code> drives: is this our event, which repo, does the signature verify, what does the payload ask for.</li><li><strong>Push</strong> — the normalized job request every source emits; everything behind the queue is source-agnostic.</li><li><strong>Queue</strong> — per-<em>job</em> pending slots with a policy (<code>latest</code> = latest-wins for gates, <code>all</code> = bounded FIFO for releases). Persisted via the <code>QueueStore</code> port in dev; durable state is the <code>ci-job</code> entity plane in fleets.</li><li><strong>Runner</strong> — how a job becomes a spawned process: <code>shell</code> (bash), <code>container</code> (podman/docker), <code>ssh</code>, <code>http</code> (remote <code>bupha agent</code>), <code>dagger</code>, <code>gha</code> (workflow dialect).</li><li><strong><code>gha</code> dialect vs <code>gha-runner</code></strong> — two different products sharing a name: <code>runner.kind = &quot;gha&quot;</code> makes bupha <em>read and execute</em><code>.github/workflows</code> YAML; <code>bupha gha-runner</code> makes bupha a self-hosted runner that <em>GitHub&#39;s service drives</em> via the actions/runner broker protocol.</li><li><strong>Status sink</strong> — where run outcomes are reported: forge commit statuses (<code>ci/bupha</code> context by default, plus per-job detail under <code>&lt;context&gt;/&lt;workflow&gt;/&lt;job&gt;</code>).</li></ul><h2 id="fleet-and-plane" tabindex="-1">Fleet and plane <a class="header-anchor" href="#fleet-and-plane" aria-label="Permalink to &quot;Fleet and plane&quot;">​</a></h2><ul><li><strong>Bundle</strong> — a <code>type: bupha</code> tamias pack: <code>tamias.yaml</code> (provider units + ingress hooks) + <code>fleet.toml</code> (a complete watcher/worker config). <code>libraries/ci-gate</code>, <code>docs-deploy</code>, <code>ci-ingress</code> are the shipped examples.</li><li><strong><code>host</code> vs <code>worker</code></strong> — the two service verbs: <code>tamias-driver-bupha host</code> runs the standalone watcher (webhook → local queue → runner → status); <code>worker</code> polls <code>ci-job</code> entities on the hypha/peregrin node and runs claimed jobs through the same pipeline. Enable ONE per ingress mode.</li><li><strong>ci-job entity</strong> — a job as a hypha entity (<code>kind=&quot;ci-job&quot;</code>, deterministic id <code>ci:{key}:{sha}:{attempt}</code>); <code>ci.*</code> ops carry enqueue/claim/renew/release/complete with fence + lease semantics.</li><li><strong><code>runs_on</code> labels</strong> — per-repo/job scheduling constraints (<code>arch=arm64</code>); a job runs only on workers whose <code>[worker] labels</code> satisfy them.</li><li><strong><code>bupha agent</code></strong> — the remote executor behind <code>kind = &quot;http&quot;</code>: tar worktree + poll over an HMAC-signed HTTP wire.</li></ul><h2 id="dev-harness" tabindex="-1">Dev harness <a class="header-anchor" href="#dev-harness" aria-label="Permalink to &quot;Dev harness&quot;">​</a></h2><ul><li><strong><code>bupha</code> command</strong> — the dev/debug CLI behind the <code>bins[]</code> shim (<code>bupha-cli</code> is lib-only): <code>run</code>, <code>doctor</code>, <code>watch</code>, <code>agent</code>, <code>gha-runner</code>, <code>import</code>, <code>deploy</code>, <code>service</code>. Production fleets run through the driver verbs, not this binary.</li><li><strong>Worktree</strong> — every run executes in a detached <code>git worktree</code> of the pushed sha at <code>&lt;base&gt;-&lt;repo&gt;[-&lt;job&gt;]-&lt;sha12&gt;</code>; never a shared dirty checkout.</li></ul>',8)])])}const g=o(c,[["render",d]]);export{u as __pageData,g as default};
